INSERT IGNORE INTO `Post` (`id`, `category`, `subCategory`, `tag`, `title`, `content`, `authorId`, `viewCount`, `createdAt`, `updatedAt`) VALUES
('1', 'info', NULL, NULL, '피아노 조율', 'Mike Bratcher 317-371-5747\n웨라에 사는 분은 아니어서 이 분이 웨라에 오실 때 맞춰서 시간 잡고 있어요. 언제 오시는 지 먼저 물어보세요~\n저는 몇 년 동안 이 분께 조율 맡기고 있어서 요즘은 연락 먼저 주실 때까지 기다려요.\n조율비: 그랜드 피아노 $155/1회 입니다. 업라이트 피아노는 이보다 저렴한 걸로 알아요.\n조율시간: 보통 1시간\n1년 이상 조율 안한 피아노는 한 번 방문시 두 번 이상 조율하기 때문에 기본 조율 비용보다 많이 나와요.', 'legacy', 0, '2026-04-22 00:15:00.000', '2026-04-22 00:15:00.000'),
('2', 'info', NULL, NULL, 'Pest Control', '웨스트라피엣 한인커뮤니티 단톡방 질문과 답변 공유합니다.\n스윗 라이언: 안녕하세요! 조금 전에 pest control 업체에서 홍보하려고 저희 집을 방문을 했는데요~ 저희도 하우스에서 살아보는건 처음이라.. 업체의 도움을 받아야 할지 감이 안오네요.. 보통 직접 약을 뿌리시나요? 다들 pest control 어떻게 하시는지 궁금합니다!\nShy Neo: 어떤 pest냐에따라 다릅니다.. 개미는 약뿌려서 퇴치가 되는 경우도 있고요.. 쥐는 다니는 통로가 있어서 덫이나 약으로는 한계가 있습니다..', 'legacy', 0, '2026-04-22 00:04:00.000', '2026-04-22 00:04:00.000'),
('3', 'info', NULL, NULL, '치과 추천해주세요', '정기점검으로 일반 성인 치과 추천 부탁해요', 'legacy', 0, '2026-04-13 20:45:00.000', '2026-04-13 20:45:00.000'),
('4', 'info', NULL, NULL, '✨ 퍼듀 평일 한국학교 The Bridge', '✨ 퍼듀 평일 한국학교 The Bridge\n2026 봄학기 학생 & 학부모 모집합니다!\n퍼듀 평일 한국학교 The Bridge는 토요 한국학교와는 별도로,\n평일에 학생과 가정이 함께 배우며 성장할 수 있도록 마련된 주중 프로그램입니다.\n아이들에게는 영어 읽기·쓰기 + 신앙적 이해 + 건강한 운동 활동,\n학부모에게는 말씀·생활 영어·커뮤니티,\n가정에는 함께 성장하는 배움의 연결을 제공합니다.\n📚 학생(4–7학년): 방과 후 화·목\n· Bible Study, Reading & Writing, Sports Activity\n💵 $60 / 4주 (교재비 별도)\n🗓 화/목 16:00-17:50\n👩‍👧 성인 프로그램(학부모 및 성인여성)\n· 바이블 스터디, 미국 생활 영어, 학부모 커뮤니티\n💵 $50 / 4주\n🗓 화/목 오전 9:30-11:30\n📍 2026년 2월 3일 시작합니다.\n📝 등록링크\nhttps://forms.gle/SfoVAUCGRSwBipr37', 'legacy', 0, '2026-01-15 13:58:00.000', '2026-01-15 13:58:00.000'),
('5', 'info', NULL, NULL, '✏️ 2026 봄학기 한국학교 개강 안내 🎉', '2026 봄 학기 한국학교가 개강합니다!\n믿음 안에서 한국어와 문화를 배우는 한국학교에 여러분을 초대합니다😊\n등록을 원하시는 분들은 아래 링크를 통해 신청해주세요!\n🗓 일정: 2026.2.7 - 2026.4.25\n⏰ 시간: 매주 토요일 9:30AM - 12:30PM\n👧 대상: 3세 - 성인\n📍 장소: 퍼듀한인장로교회\nhttps://docs.google.com/forms/d/e/1FAIpQLSffpPQBlCS-nDFQUIs5LoqyTHMx9loAKYXVhqstVMLLm4i60Q/viewform', 'legacy', 0, '2026-01-15 13:54:00.000', '2026-01-15 13:54:00.000'),
('6', 'info', NULL, NULL, '2025년 Thanksgiving Market  날짜&시간', 'Holiday downtown Farmers Market\nDates: November 22, 2025\nTimes: 11 AM - 2 PM\nAddress:\n100 N. 5th Street\nLafayette, IN 47901\nLocation: 5th Street between Columbia & mid-block of Ferry, and Main Street between 4th and 6th street\nWest Lafayette Thanksgiving Market\nDates: November 26, 2025\nTimes: 2 - 6 PM\nAddress:\n1101 Kalberer Road, West Lafayette, IN 47906\nLocation: Wellness Center', 'legacy', 0, '2025-11-15 23:03:00.000', '2025-11-15 23:03:00.000'),
('7', 'info', NULL, NULL, 'Christkindlmarkt, Carmel, IN', '해마다 추수감사절 무렵부터 시작해서 크리스마스 이브까지만 열리는 독일 전통 시장 소개합니다.\n다양한 볼거리, 먹을거리, shop들, 아이스링크 등이 있어서 성별/나이 상관없이 모두 즐길 수 있는 곳이에요.\n장소는 Carmel, IN 이고, 구글맵에서 검색하면 바로 나옵니다.\n웹사이트:\nhttps://www.carmelchristkindlmarkt.com/\n2025년 일정:\n11월 22일(토) - 12월 24일\n월, 화 Closed\n수, 목 4 - 9 PM\n금, 토 12 - 9 PM\n일 12 - 8 PM', 'legacy', 0, '2025-10-28 19:47:00.000', '2025-10-28 19:47:00.000'),
('8', 'info', NULL, NULL, '집 보험 커버 지붕 수리 (6월 우박 관련)', '지난 6월에 저희 동네를 강타한 우박 (hail)때문에 혹시 지붕이 파손되었는지 roofing contractors에 연락해서 한번 체크해보세요~\n지붕교체에 해당되면 집 보험으로 100% 커버된다고 합니다.\n혹시 우박이 떨어졌던 시기에 여행중이셨던 분들을 위해 구글에서 퍼온 글 공유합니다.', 'legacy', 0, '2025-10-21 22:49:00.000', '2025-10-21 22:49:00.000'),
('9', 'info', NULL, NULL, '[식당] Strings Ramen', 'https://maps.app.goo.gl/8MLhkNLaA9rNVC576\n캠퍼스 근처에 위치한 일식라멘 집이라 사람들이 많은듯.\n비쌈. 뭐 외식이 다 그렇긴 한데 그래도 비쌈\n맛 그냥... 그럼. 라멘집인데 면이 왜 미지근하게 나와 한 적이 있었음.', 'legacy', 0, '2025-10-18 21:58:00.000', '2025-10-18 21:58:00.000'),
('10', 'info', NULL, NULL, '[식당] Green Leaf Vietnamese', 'https://maps.app.goo.gl/NG6mbtsfE4m59fcM6\n쌀국수 먹어봤는데 양이 좀 적은 편이고. 그냥 어디 쌀국수 액기스 사와서 뜨거운 물에 풀어준 것 같음.\n가게 더러움.\n해주는거 별로 없는데 Tip은 왜 물어보나 싶음.\n다시 안감.', 'legacy', 0, '2025-10-18 21:54:00.000', '2025-10-18 21:54:00.000'),
('11', 'jobs', NULL, NULL, '모집공고 (HR & 전산)', '회사 위치 : 하트퍼드 & 헌팅턴\n생산 제품 : ESS 관련\n모집 분야 : (1)HR 매니저 또는 담당자 (2) 전산(신입,경력)\nSAP 경험자 우대\n입사후 1달간 본사 체류하면서 직무 교육 실시\n입사 희망 시기 : 26.02월 (조정 가능)\n근무조건 : 한국 상장 회사이며 개별 컨택 주시면 회사 정보 공유 예정', 'legacy', 0, '2025-10-21 19:22:00.000', '2025-10-21 19:22:00.000'),
('12', 'jobs', NULL, NULL, 'Admin Officer, 현장 엔지니어 모집(배터리 공장)', '-채용 공고-\n회사: 배터리 공장 환경 플랜트 업체 HKENE USA INC\n근무 지역: 미국 인디애나 코코모\n모집 분야: Admin Officer, 현장 엔지니어\n모집 대상: Admin Officer(초보도 가능), 현장 엔지니어 (경력 2년 이상), 대졸\n연봉: 경력에 따라 대우\n혜택: 건강보험, 퇴직 연금, 자기운전 보조 경비, 교육지원정책, 성과급(대기업급)\n지원 대상자: 합법적으로 일을 할수 있는 비자 소지자, 영어/한국어 가능자\n관심 있으신 분들은 아래로 지원 바랍니다.\nroca77@hkene.co.kr', 'legacy', 0, '2025-10-16 18:05:00.000', '2025-10-16 18:05:00.000'),
('13', 'jobs', NULL, NULL, '채용공고(지역: 코코모)', '<채용 공고>\n회사: 삼성 협력업체\n근무지역: 인디애나 코코모 (Kokomo, IN)\n모집부문: 제조 부문\n모집대상: 남성 (35세~45세)\n연봉 범위: $55,000 ~ $65,000\n복지 혜택: 기숙사 제공\n근무조건: 신체 건강하며 즉시 출근 가능한 분, 한국어 가능자\n<연락처>\n수신 이메일: likeolivetree@gmail.com\n관심 있으신 분은 개별 문의 바랍니다.', 'legacy', 0, '2025-10-15 18:40:00.000', '2025-10-15 18:40:00.000'),
('14', 'tutoring', 'offer-tutor', NULL, '과외교사 홍보 양식', '과외 교사 홍보 글 작성 안내\n아래 양식을 복사하여 작성해 주세요.\n정보가 누락된 경우 게시가 제한될 수 있습니다.', 'legacy', 0, '2026-02-08 03:51:00.000', '2026-02-08 03:51:00.000'),
('15', 'tutoring', 'offer-tutor', NULL, '영어 원어민 과외 선생님', '안녕하세요,\n영어 과외 선생님을 구하시는 분들께 좋은 선생님 한 분 소개합니다. Shelley Mathis (셸리 매띠스) 선생님께서 직접 써주신, 아래 소개 글 보시고 관심 있으신 분들은 연락해보세요~', 'legacy', 0, '2026-04-04 17:02:00.000', '2026-04-04 17:02:00.000'),
('16', 'tutoring', 'offer-tutor', NULL, '메쓰존 튜터 (그룹&개인)', '1. 기본 정보\n이름: John Lee\n거주 지역: West Lafayette\n온라인 수업 가능 여부: 가능\n2. 학력 및 전공\n학교명: 아주대학교, 예일대학교\n전공: Biomedical Engineering', 'legacy', 0, '2026-03-31 14:57:00.000', '2026-03-31 14:57:00.000'),
('17', 'tutoring', 'offer-tutor', NULL, '수학 과외 안내', '1. 기본 정보\n이름: Thomas Kim\n거주 지역: 웨스트라파엣\n온라인 수업 가능 여부: 가능\n2. 학력 및 전공\n학교명: 서울대학교\n전공: 지구환경시스템공학부 박사 (2002년 졸업)', 'legacy', 0, '2026-03-28 22:08:00.000', '2026-03-28 22:08:00.000'),
('18', 'housing', 'rent', NULL, '샌츄리 아파트 선착순 프로모션', '센츄리 아파트 2b2b 또는 Studio 1년 계약시 선착순으로 $1,250 gift card 증정 합니다. (소진시 종료되고 6/15일 까지 입주)', 'legacy', 0, '2026-04-23 06:55:00.000', '2026-04-23 06:55:00.000'),
('19', 'housing', NULL, NULL, '웨스트라피엣 부동산 문의', '', 'legacy', 0, '2026-04-06 15:28:00.000', '2026-04-06 15:28:00.000'),
('20', 'housing', 'rent', NULL, 'Sk 근처 웨스트라피엣 하우스 쉐어 렌트', '자세한 사항 /사진/ 쇼잉 문의는 전화/문자/ email\n702-238-3226\nEmoon@truebloodre.com', 'legacy', 0, '2026-03-30 08:57:00.000', '2026-03-30 08:57:00.000'),
('21', 'faq', NULL, NULL, '[필독] 웨스트라피엣 한인 커뮤니티 웹사이트는 어떤 곳인가요?', 'West Lafayette Korea\n는 웨스트라피엣에 거주하는 모든 한인들을 위한 커뮤니티 플랫폼입니다.\n우리는 한인 학생과 연구자, 직장인, 그리고 이 지역을 삶의 터전으로 삼고 있는 모든 한인들이 자유롭게 소통하고 정보를 나누며 서로 연결되고 함께 성장할 수 있는 공간을 지향합니다.', 'legacy', 0, '2025-09-21 15:26:00.000', '2025-09-21 15:26:00.000'),
('22', 'faq', NULL, NULL, 'Farmers Market (파머스 마켓)', '#파머스 마켓이 열리는 기간은\n5월 - 10월\n입니다.\nWest Lafayette Farmers Market\n요일: 수요일\n시간: 3:30 PM - 7:30 PM\n위치: Cumberland Park에 주차\n주소: 3065 N Salisbury St, West Lafayette, IN 47906', 'legacy', 0, '2025-11-15 22:50:00.000', '2025-11-15 22:50:00.000'),
('23', 'faq', NULL, NULL, '공립도서관(Public library) 이용 방법', 'West Lafayette에는\nWest Lafayette Public Library\n와\nKlondike Library\n가 있으며, 두 도서관을 운영하는 상위 기관이 서로 달라 도서관에서 책을 대출하기 위해서는 각각의 도서관 카드(library card)를 만드셔야 합니다.', 'legacy', 0, '2025-10-22 22:31:00.000', '2025-10-22 22:31:00.000'),
('24', 'faq', NULL, NULL, '한국 식재료/식품을 구입할 수 있는 곳', '하나 마켓\n3457 Bethel Dr A, West Lafayette, IN 47906\nCUBE market (편의점)\n150 S Chauncey Ave Suite 140, West Lafayette, IN 47906\n우리 동네 중국마트\nBetter World Market\n402 Brown St, West Lafayette, IN 47906\nAsia Global Market\n2400 Yeager Rd, West Lafayette, IN 47906', 'legacy', 0, '2025-10-22 21:56:00.000', '2025-10-22 21:56:00.000'),
('25', 'faq', NULL, NULL, '교회 & 성당 정보', '퍼듀한인장로교회\nhttps://www.purduekoreanchurch.org/\n주소:\n4505 IN-26, West Lafayette, IN 47906', 'legacy', 0, '2025-10-21 23:04:00.000', '2025-10-21 23:04:00.000'),
('26', 'faq', NULL, NULL, '학군/학교 정보 알려주세요.', 'West Lafayette에는 West Lafayette Community School Corporation (WLCSC)과 Tippecanoe School Corporation (TSC), 이렇게\n2개의 학군\n이 있습니다.', 'legacy', 0, '2025-09-26 00:22:00.000', '2025-09-26 00:22:00.000'),
('27', 'faq', NULL, NULL, '데이케어 정보 알려주세요.', '데이케어 이용 대상: 생후 6주 - 만 5세 (Kindergarten 입학 전)', 'legacy', 0, '2025-09-26 00:13:00.000', '2025-09-26 00:13:00.000');
